#[test]
fn handles_empty_quoted_values() {
    let content = "DOUBLE=\"\"\nSINGLE=''";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("DOUBLE"), Some(&"".to_string()));
    assert_eq!(vars.get("SINGLE"), Some(&"".to_string()));
}

#[test]
fn mismatched_quotes_treated_as_literal() {
    let content = "MIX1=\"value'\nMIX2='value\"";

    let vars = EnvFileParser::parse(content).unwrap();

    // Mismatched quotes should not be stripped
    assert_eq!(vars.get("MIX1"), Some(&"\"value'".to_string()));
    assert_eq!(vars.get("MIX2"), Some(&"'value\"".to_string()));
}

#[test]
fn single_quote_char_not_stripped() {
    let content = "Q1=\"\nQ2='";

    let vars = EnvFileParser::parse(content).unwrap();

    // A lone quote character is not a quoted value
    assert_eq!(vars.get("Q1"), Some(&"\"".to_string()));
    assert_eq!(vars.get("Q2"), Some(&"'".to_string()));
}

#[test]
fn escaped_quotes_inside_double_quotes() {
    // The parser does NOT process escape sequences — it only strips
    // the outermost matching quotes. Backslashes are kept verbatim.
    let content = r#"KEY="value with \"escaped\" quotes""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // The outer quotes are `"value with \"escaped\" quotes"`.
    // starts_with('"') and ends_with('"') both match, so the
    // first and last characters are stripped.
    let val = vars.get("KEY").unwrap();
    assert_eq!(val, r#"value with \"escaped\" quotes"#);
}

#[test]
fn escaped_characters_in_value_kept_verbatim() {
    let content = r#"PATH="C:\\Users\\name""#;

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("PATH"), Some(&r"C:\\Users\\name".to_string()));
}

#[test]
fn newline_escape_kept_as_literal() {
    let content = r#"MSG="hello\nworld""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // \n is NOT converted to a real newline — kept as two chars
    assert_eq!(vars.get("MSG"), Some(&r"hello\nworld".to_string()));
}

#[test]
fn value_with_hash_is_not_treated_as_comment() {
    let content = "COLOR=#FF0000\nCHANNEL=room#general";

    let vars = EnvFileParser::parse(content).unwrap();

    // Hash in a value is part of the value (no inline comment stripping)
    assert_eq!(vars.get("COLOR"), Some(&"#FF0000".to_string()));
    assert_eq!(vars.get("CHANNEL"), Some(&"room#general".to_string()));
}

#[test]
fn quoted_value_containing_hash() {
    let content = "KEY=\"value # not a comment\"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"value # not a comment".to_string()));
}

#[test]
fn quotes_in_middle_of_value_not_stripped() {
    let content = "KEY=some\"value\"here";

    let vars = EnvFileParser::parse(content).unwrap();

    // Quotes do not surround the entire value, so they stay
    assert_eq!(vars.get("KEY"), Some(&"some\"value\"here".to_string()));
}

#[test]
fn whitespace_inside_quotes_preserved() {
    let content = "KEY=\"  padded  \"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"  padded  ".to_string()));
}

#[test]
fn trailing_whitespace_on_unquoted_value_trimmed() {
    // The value part is trimmed by parse_line before unquote
    let content = "KEY=value   ";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
}

